'use strict';

var baseAccountConnector = require('@web3auth/no-modal/connectors/base-account-connector');



Object.keys(baseAccountConnector).forEach(function (k) {
	if (k !== 'default' && !Object.prototype.hasOwnProperty.call(exports, k)) Object.defineProperty(exports, k, {
		enumerable: true,
		get: function () { return baseAccountConnector[k]; }
	});
});
